const listOperatorJobsScoped = `-- name: ListOperatorJobsScoped :many

SELECT a.id AS assignment_id, a.status::text AS assignment_status, b.id AS booking_id, b.reference, b.status::text AS booking_status,
       lower(b.period)::timestamptz AS starts_at, upper(b.period)::timestamptz AS ends_at,
       e.title AS equipment_title, COALESCE(e.registration_no, '')::text AS registration_no,
       ad.line1 AS site_line1, ad.city AS site_city, cu.display_name AS customer_name,
       COALESCE((SELECT c.agreed_amount_paise FROM driver_compensations c WHERE c.booking_id = b.id AND c.driver_user_id = $1),0)::bigint AS driver_payment_paise,
       COALESCE((SELECT c.status FROM driver_compensations c WHERE c.booking_id = b.id AND c.driver_user_id = $1),'not_set')::text AS driver_payment_status,
       ST_Y(b.site_location::geometry)::float8 AS site_lat, ST_X(b.site_location::geometry)::float8 AS site_lng
FROM operator_assignments a
JOIN bookings b ON b.id = a.booking_id
JOIN equipment e ON e.id = b.equipment_id
JOIN addresses ad ON ad.id = b.site_address_id
JOIN organizations cu ON cu.id = b.customer_org_id
WHERE a.operator_user_id = $1
  AND CASE WHEN $2::text = 'current'
        THEN a.status IN ('assigned', 'accepted') AND b.status IN ('operator_assigned', 'confirmed', 'dispatched', 'on_site', 'active', 'extension_requested', 'return_initiated', 'cancellation_requested')
        WHEN $2::text = 'history'
        THEN NOT (a.status IN ('assigned', 'accepted') AND b.status IN ('operator_assigned', 'confirmed', 'dispatched', 'on_site', 'active', 'extension_requested', 'return_initiated', 'cancellation_requested'))
        ELSE true END
  AND EXISTS (SELECT 1 FROM operator_profiles op JOIN operator_skills sk ON sk.operator_user_id=op.user_id
              JOIN equipment_models em ON em.category_id=sk.category_id
              WHERE op.user_id=a.operator_user_id AND em.id=e.model_id)
  AND ($3::timestamptz IS NULL OR upper(b.period) > $3::timestamptz)
  AND ($4::timestamptz IS NULL OR lower(b.period) < $4::timestamptz)
ORDER BY CASE WHEN $2::text = 'history' THEN -extract(epoch FROM lower(b.period)) ELSE extract(epoch FROM lower(b.period)) END
LIMIT $5
`

type ListOperatorJobsScopedParams struct {
	OperatorUserID uuid.UUID  `json:"operator_user_id"`
	Scope          string     `json:"scope"`
	FromAt         *time.Time `json:"from_at"`
	ToAt           *time.Time `json:"to_at"`
	Lim            int32      `json:"lim"`
}

type ListOperatorJobsScopedRow struct {
	AssignmentID        uuid.UUID `json:"assignment_id"`
	AssignmentStatus    string    `json:"assignment_status"`
	BookingID           uuid.UUID `json:"booking_id"`
	Reference           string    `json:"reference"`
	BookingStatus       string    `json:"booking_status"`
	StartsAt            time.Time `json:"starts_at"`
	EndsAt              time.Time `json:"ends_at"`
	EquipmentTitle      string    `json:"equipment_title"`
	RegistrationNo      string    `json:"registration_no"`
	SiteLine1           string    `json:"site_line1"`
	SiteCity            string    `json:"site_city"`
	CustomerName        string    `json:"customer_name"`
	DriverPaymentPaise  int64     `json:"driver_payment_paise"`
	DriverPaymentStatus string    `json:"driver_payment_status"`
	SiteLat             float64   `json:"site_lat"`
	SiteLng             float64   `json:"site_lng"`
}

// ---- operator jobs ------------------------------------------------------------------------------
// scope 'current' = open assignments on bookings still running; 'history'
// = everything else the operator was assigned (declined, replaced, done).
func (q *Queries) ListOperatorJobsScoped(ctx context.Context, arg ListOperatorJobsScopedParams) ([]ListOperatorJobsScopedRow, error) {
	rows, err := q.db.Query(ctx, listOperatorJobsScoped,
		arg.OperatorUserID,
		arg.Scope,
		arg.FromAt,
		arg.ToAt,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOperatorJobsScopedRow{}
	for rows.Next() {
		var i ListOperatorJobsScopedRow
		if err := rows.Scan(
			&i.AssignmentID,
			&i.AssignmentStatus,
			&i.BookingID,
			&i.Reference,
			&i.BookingStatus,
			&i.StartsAt,
			&i.EndsAt,
			&i.EquipmentTitle,
			&i.RegistrationNo,
			&i.SiteLine1,
			&i.SiteCity,
			&i.CustomerName,
			&i.DriverPaymentPaise,
			&i.DriverPaymentStatus,
			&i.SiteLat,
			&i.SiteLng,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

