const ownerSideRecipients = `-- name: OwnerSideRecipients :many

SELECT DISTINCT ur.user_id
FROM user_roles ur
WHERE ur.organization_id = $1 AND ur.revoked_at IS NULL
  AND (ur.role_code IN ('owner', 'org_admin')
       OR (ur.role_code = 'fleet_manager' AND (
             COALESCE((SELECT f.all_equipment FROM fleet_manager_profiles f WHERE f.user_id = ur.user_id AND f.organization_id = $1), false)
             AND NOT is_restricted(ur.user_id, 'fleet_management')
             OR EXISTS (SELECT 1 FROM fleet_manager_scope s
                         WHERE s.user_id = ur.user_id AND s.organization_id = $1
                           AND s.equipment_id = COALESCE($2::uuid,
                                                         (SELECT b.equipment_id FROM bookings b WHERE b.id = $3::uuid))))))
`

type OwnerSideRecipientsParams struct {
	OrgID       uuid.NullUUID `json:"org_id"`
	EquipmentID uuid.NullUUID `json:"equipment_id"`
	BookingID   uuid.NullUUID `json:"booking_id"`
}

// ---- notifications: owner-side recipients ---------------------------------------------------------
// Owners and org admins always; fleet managers only when the booking's (or
// the named) machine is in their scope, or they manage every machine.
func (q *Queries) OwnerSideRecipients(ctx context.Context, arg OwnerSideRecipientsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, ownerSideRecipients, arg.OrgID, arg.EquipmentID, arg.BookingID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var user_id uuid.UUID
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const replaceAssignment = `-- name: ReplaceAssignment :execrows
UPDATE operator_assignments SET status = 'replaced'
WHERE booking_id = $1 AND status IN ('assigned', 'accepted')
`

// The owner swaps the operator: the open assignment is marked replaced.
func (q *Queries) ReplaceAssignment(ctx context.Context, bookingID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, replaceAssignment, bookingID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

